package net.officefloor.hq.app.claim;

/** Where a claim is in its life: only OPEN and SETTLED claims count toward the totals. */
public enum ClaimStatus {
    DRAFT, OPEN, SETTLED, VOID;

    /** The status a change takes this claim to, or null when the change is not allowed from here. */
    public ClaimStatus after(ClaimStatusChange change) {
        return switch (change) {
            case OPEN -> this == DRAFT ? OPEN : null;
            case SETTLE -> this == OPEN ? SETTLED : null;
            case VOID -> this == DRAFT || this == OPEN ? VOID : null;
        };
    }
}
package net.officefloor.hq.app.claim;

/** A change of a claim's status, named by the last path segment, with the audit event it writes. */
public enum ClaimStatusChange {
    OPEN("CLAIM_OPENED"), SETTLE("CLAIM_SETTLED"), VOID("CLAIM_VOIDED");

    private final String event;

    ClaimStatusChange(String event) {
        this.event = event;
    }

    public String event() {
        return event;
    }

    /** The change named in the path (open, settle or void), or null when there is no such change. */
    public static ClaimStatusChange of(String name) {
        for (ClaimStatusChange change : values()) {
            if (change.name().equalsIgnoreCase(name)) {
                return change;
            }
        }
        return null;
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import net.officefloor.hq.app.Audit;
import java.time.LocalDate;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.role.Role;
import net.officefloor.hq.app.role.Roles;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.SheetClock;
import org.springframework.stereotype.Service;

/** Moves a claim to the status a change takes it to, refusing a change its status does not allow; shared by a
 *  claim's own status buttons and the bulk actions. */
@Service
public class ClaimStatusChanger {

    private final Claims claims;
    private final People people;
    private final Rates rates;
    private final Periods periods;
    private final Roles roles;
    private final Settings settings;
    private final SheetClock clock;
    private final Audit audit;
    private final Rollup rollup;

    public ClaimStatusChanger(Claims claims, People people, Rates rates, Periods periods, Roles roles, Settings settings,
            SheetClock clock, Audit audit, Rollup rollup) {
        this.claims = claims;
        this.people = people;
        this.rates = rates;
        this.periods = periods;
        this.roles = roles;
        this.settings = settings;
        this.clock = clock;
        this.audit = audit;
        this.rollup = rollup;
    }

    /** Applies the change to the claim, writing nothing when it is refused. */
    public void change(String sheet, String user, Claim claim, ClaimStatusChange requested)
            throws InvalidClaimStatusChangeException {
        if (periods.closedOn(sheet, LocalDate.parse(claim.date()))) {
            throw new InvalidClaimStatusChangeException("A claim dated inside a closed period cannot change status");
        }
        // Four eyes: the user who opened a claim may not settle it.
        if (requested == ClaimStatusChange.SETTLE && user.equals(claim.openedBy())) {
            throw new InvalidClaimStatusChangeException("The user who opened a claim cannot settle it");
        }
        Person person = people.find(sheet, claim.person());
        // A clerk settles only a due at or below the sheet's clerk limit (a due of n/a is within any limit);
        // a steward settles anything.
        if (requested == ClaimStatusChange.SETTLE && Role.CLERK.equals(roles.of(sheet, user))) {
            BigDecimal limit = settings.clerkLimit(sheet);
            BigDecimal due = claim.due(rates.list(sheet), person.gradeOn(claim.date()), settings.floor(sheet),
                    settings.late(sheet, clock.today(sheet)));
            if (limit != null && due != null && due.compareTo(limit) > 0) {
                throw new InvalidClaimStatusChangeException("A clerk cannot settle a due above the clerk limit");
            }
        }
        Rollup.Snapshot before = rollup.take(sheet);
        ClaimStatus next = claim.status().after(requested);
        // Conditional on the status read, so a concurrent change by another user is refused, not overwritten.
        if (next == null || !claims.changeStatus(sheet, claim.id(), claim.status(), next)) {
            throw new InvalidClaimStatusChangeException(
                    "A " + claim.status() + " claim does not allow " + requested.name().toLowerCase());
        }
        // Opening gives the sheet's next number, or, while the sheet numbers by period from on or before its today,
        // the next number in the claim's period (X for none); a voided claim keeps the number it had (never reused).
        Claim changed = claim;
        if (requested == ClaimStatusChange.OPEN) {
            LocalDate from = settings.periodNumberingFrom(sheet);
            if (from != null && !clock.today(sheet).isBefore(from)) {
                String period = periods.nameOn(sheet, LocalDate.parse(claim.date()));
                String key = period == null ? "" : period;
                changed = claim.withPeriodNumber((period == null ? "X" : period) + "-" + claims.nextPeriodNumber(sheet, key));
                claims.setPeriodNumber(sheet, claim.id(), changed.periodNumber());
            } else {
                changed = claim.withNumber(claims.nextNumber(sheet));
                claims.setNumber(sheet, claim.id(), changed.number());
            }
            claims.setOpenedBy(sheet, claim.id(), user);
        }
        String fields = changed.statusAuditFields(person.name());
        // Settling fixes the due at the person's grade rate in force on the claim's date (or the figure its
        // statement bound), with its late charge frozen in; with no rate there is nothing to fix, so it stays live.
        if (requested == ClaimStatusChange.SETTLE) {
            BigDecimal due = claim.due(rates.list(sheet), person.gradeOn(claim.date()), settings.floor(sheet),
                    settings.late(sheet, clock.today(sheet)));
            claims.setSettledDue(sheet, claim.id(), due);
            fields += " due=" + (due == null ? "n/a" : due.toPlainString());
        }
        audit.record(requested.event() + " sheet=" + sheet + " by=" + user + " " + fields);
        rollup.record(sheet, user, before);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** Moves the claim to the status the change takes it to, refusing a change its status does not allow. */
public class ApplyClaimStatus {
    public void apply(@PathVariable("sheet") String sheet, @PathVariable("change") String change,
            @RequestParam("user") String user, @Val Claim claim, ClaimStatusChanger changer)
            throws InvalidClaimStatusChangeException {
        ClaimStatusChange requested = ClaimStatusChange.of(change);
        if (requested == null) {
            throw new InvalidClaimStatusChangeException("No such status change: " + change);
        }
        changer.change(sheet, user, claim, requested);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.rate.Rate;

/**
 * A claim as the screen shows it: amount with two decimals, date (ISO yyyy-MM-dd), note, status and its number on
 * the sheet (given when opened and kept once voided; null while a draft), and its due fixed when settled (two decimals;
 * null until settled, and when the grade had no rate then), and the user who opened it (null until opened), and
 * whether its person's last statement bound it, with the figure it bound (null when the grade had no rate then), and
 * the number of the claim it corrects (null unless it is a correction), and the date it rounds on: its own, or for
 * a correction the date of the claim it corrects, and its number within its period (<period>-<n>, or X-<n> in no
 * period) when it was opened while the sheet numbered by period, in place of a number on the sheet (null otherwise).
 */
public record Claim(long id, long person, String amount, String date, String note, ClaimStatus status,
        Integer number, String settledDue, String openedBy, boolean stated, String statedDue, String corrects,
        String roundsOn, String periodNumber) {

    /** Whether this claim is a correction: a negative amount, naming the number (as it shows) of the settled claim it corrects. */
    public boolean correction() {
        return amount.startsWith("-");
    }

    /** The audit fields of this claim for the named person, as {@link ClaimInput#auditFields}. */
    public String auditFields(String person) {
        return "person=" + person + " amount=" + amount + " date=" + date;
    }

    /** This claim, numbered: its audit fields end with number=<number> when it has one. */
    public Claim withNumber(Integer number) {
        return new Claim(id, person, amount, date, note, status, number, settledDue, openedBy, stated, statedDue, corrects, roundsOn, periodNumber);
    }

    /** This claim, numbered within its period: its audit fields end with number=<period number>. */
    public Claim withPeriodNumber(String periodNumber) {
        return new Claim(id, person, amount, date, note, status, number, settledDue, openedBy, stated, statedDue, corrects, roundsOn, periodNumber);
    }

    /** This claim, settled with its due fixed (null when its grade had no rate). */
    public Claim withSettledDue(String settledDue) {
        return new Claim(id, person, amount, date, note, status, number, settledDue, openedBy, stated, statedDue, corrects, roundsOn, periodNumber);
    }

    /** The number the claim shows: its number within its period, else its number on the sheet; null for none. */
    public String shownNumber() {
        return periodNumber != null ? periodNumber : number == null ? null : number.toString();
    }

    /** The audit fields of a status change: {@link #auditFields} then number=<number> when it has one. */
    public String statusAuditFields(String person) {
        String shown = shownNumber();
        return auditFields(person) + (shown == null ? "" : " number=" + shown);
    }

    /** Whether this claim counts toward the totals: OPEN and SETTLED claims do. */
    public boolean counts() {
        return status == ClaimStatus.OPEN || status == ClaimStatus.SETTLED;
    }

    /** Whether this claim counts toward the live totals when its person is {@code held}: then only SETTLED does. */
    public boolean counts(boolean held) {
        return held ? status == ClaimStatus.SETTLED : counts();
    }

    /**
     * Whether this claim keeps a figure whatever the rates: fixed when settled, or bound by a statement (a claim
     * settled or bound when its grade had no rate keeps none).
     */
    public boolean fixed() {
        return settledDue != null || (stated && statedDue != null);
    }

    /**
     * This claim's due: its {@link #figure} plus, while it is overdue, its late charge (settling fixes the charge
     * in); null when there is no figure.
     */
    public BigDecimal due(List<Rate> rates, String grade, BigDecimal floor, Late late) {
        BigDecimal figure = figure(rates, grade, floor, late.rounding(this));
        return figure == null || settledDue != null ? figure : figure.add(late.charge(this, figure));
    }

    /**
     * This claim's figure: the due fixed when settled, else the one its statement bound, else its amount at the
     * grade's rate in force on its date, raised to at least the sheet's floor (a correction has no floor); null when
     * there is none.
     */
    public BigDecimal figure(List<Rate> rates, String grade, BigDecimal floor) {
        return figure(rates, grade, floor, RoundingMode.HALF_EVEN);
    }

    /** This claim's {@link #figure}, its live figure rounded by the mode. */
    public BigDecimal figure(List<Rate> rates, String grade, BigDecimal floor, RoundingMode rounding) {
        if (settledDue != null) {
            return new BigDecimal(settledDue);
        }
        if (stated) {
            return statedDue == null ? null : new BigDecimal(statedDue);
        }
        BigDecimal live = Rate.due(amount, Rate.on(rates, grade, LocalDate.parse(date)), rounding);
        return live == null || correction() ? live : live.max(floor);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.sql.Date;
import java.util.List;
import org.springframework.dao.DuplicateKeyException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

/** The claims kept per sheet, each belonging to a person on that sheet. */
@Repository
public class Claims {

    private static final RowMapper<Claim> ROW = (rs, i) -> new Claim(rs.getLong("id"), rs.getLong("person"),
            rs.getBigDecimal("amount").setScale(2, RoundingMode.UNNECESSARY).toPlainString(),
            rs.getDate("claimed_on").toLocalDate().toString(), rs.getString("note"),
            ClaimStatus.valueOf(rs.getString("status")), rs.getObject("number_on_sheet", Integer.class),
            rs.getBigDecimal("settled_due") == null ? null
                    : rs.getBigDecimal("settled_due").setScale(2, RoundingMode.UNNECESSARY).toPlainString(),
            rs.getString("opened_by"), rs.getBoolean("stated"),
            rs.getBigDecimal("stated_due") == null ? null
                    : rs.getBigDecimal("stated_due").setScale(2, RoundingMode.UNNECESSARY).toPlainString(),
            rs.getString("corrects"), rs.getDate("rounds_on").toLocalDate().toString(),
            rs.getString("period_number"));

    // A claim rounds on its own date; a correction on the date of the claim it corrects (its own when none has it).
    private static final String COLUMNS = "SELECT claim.id, claim.person, claim.amount, claim.claimed_on, claim.note, claim.status,"
            + " claim.number_on_sheet, claim.settled_due, claim.opened_by, claim.stated, claim.stated_due, claim.corrects,"
            + " claim.period_number, COALESCE(corrected.claimed_on, claim.claimed_on) AS rounds_on FROM claim"
            + " LEFT JOIN claim corrected ON corrected.sheet = claim.sheet AND "
            + " COALESCE(corrected.period_number, CAST(corrected.number_on_sheet AS VARCHAR)) = claim.corrects";

    private final JdbcTemplate jdbc;

    public Claims(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** Every claim on the sheet, newest first. */
    public List<Claim> list(String sheet) {
        return jdbc.query(COLUMNS + " WHERE claim.sheet = ? ORDER BY claim.id DESC", ROW, sheet);
    }

    public Claim find(String sheet, long id) {
        List<Claim> found = jdbc.query(COLUMNS + " WHERE claim.sheet = ? AND claim.id = ?", ROW, sheet, id);
        return found.isEmpty() ? null : found.get(0);
    }

    /** The claim showing this number on the sheet (within its period, or on the sheet), or null when none does. */
    public Claim findByNumber(String sheet, String number) {
        List<Claim> found = jdbc.query(COLUMNS + " WHERE claim.sheet = ?"
                + " AND COALESCE(claim.period_number, CAST(claim.number_on_sheet AS VARCHAR)) = ?", ROW, sheet, number);
        return found.isEmpty() ? null : found.get(0);
    }

    public void add(String sheet, long person, ClaimInput input) {
        jdbc.update("INSERT INTO claim (sheet, person, amount, claimed_on, note, corrects) VALUES (?, ?, ?, ?, ?, ?)",
                sheet, person, input.amount(), Date.valueOf(input.date()), input.note(), input.corrects());
    }

    /** Edits a draft claim: false when it is no longer a draft. */
    public boolean update(String sheet, long id, ClaimInput input) {
        return jdbc.update(
                "UPDATE claim SET amount = ?, claimed_on = ?, note = ?, corrects = ? WHERE sheet = ? AND id = ? AND status = 'DRAFT'",
                input.amount(), Date.valueOf(input.date()), input.note(), input.corrects(), sheet, id) == 1;
    }

    /** Moves the claim from one status to another: false when it no longer has the status it was read with. */
    public boolean changeStatus(String sheet, long id, ClaimStatus from, ClaimStatus to) {
        return jdbc.update("UPDATE claim SET status = ? WHERE sheet = ? AND id = ? AND status = ?", to.name(), sheet,
                id, from.name()) == 1;
    }

    /** Fixes the claim's due as it is settled, or leaves none with null. */
    public void setSettledDue(String sheet, long id, BigDecimal due) {
        jdbc.update("UPDATE claim SET settled_due = ? WHERE sheet = ? AND id = ?", due, sheet, id);
    }

    /** Binds the claim to a statement's figure (null when its grade had no rate), or unbinds it when not stated. */
    public void setStated(String sheet, long id, boolean stated, BigDecimal due) {
        jdbc.update("UPDATE claim SET stated = ?, stated_due = ? WHERE sheet = ? AND id = ?", stated, due, sheet, id);
    }

    /** Records the user who opened the claim. */
    public void setOpenedBy(String sheet, long id, String user) {
        jdbc.update("UPDATE claim SET opened_by = ? WHERE sheet = ? AND id = ?", user, sheet, id);
    }

    /** Sets the claim's number on the sheet, or clears it with null. */
    public void setNumber(String sheet, long id, Integer number) {
        jdbc.update("UPDATE claim SET number_on_sheet = ? WHERE sheet = ? AND id = ?", number, sheet, id);
    }

    /** Sets the claim's number within its period. */
    public void setPeriodNumber(String sheet, long id, String periodNumber) {
        jdbc.update("UPDATE claim SET period_number = ? WHERE sheet = ? AND id = ?", periodNumber, sheet, id);
    }

    /**
     * Takes the next number in the sheet's period of the name ("" for the claims in no period): 1 first, then 2,
     * and so on, each period counting on its own. Locked as {@link #nextNumber}.
     */
    public int nextPeriodNumber(String sheet, String period) {
        while (true) {
            if (jdbc.update("UPDATE claim_period_number SET last_number = last_number + 1 WHERE sheet = ? AND period = ?",
                    sheet, period) == 1) {
                return jdbc.queryForObject("SELECT last_number FROM claim_period_number WHERE sheet = ? AND period = ?",
                        Integer.class, sheet, period);
            }
            try {
                jdbc.update("INSERT INTO claim_period_number (sheet, period, last_number) VALUES (?, ?, 1)", sheet, period);
                return 1;
            } catch (DuplicateKeyException raced) {
                // Another user took the period's first number at the same moment: take the one after it.
            }
        }
    }

    /**
     * Takes the sheet's next claim number: 1 first, then 2, and so on. The counter row stays locked until the
     * transaction ends, so two claims opened at once get different numbers.
     */
    public int nextNumber(String sheet) {
        while (true) {
            if (jdbc.update("UPDATE claim_number SET last_number = last_number + 1 WHERE sheet = ?", sheet) == 1) {
                return jdbc.queryForObject("SELECT last_number FROM claim_number WHERE sheet = ?", Integer.class,
                        sheet);
            }
            try {
                jdbc.update("INSERT INTO claim_number (sheet, last_number) VALUES (?, 1)", sheet);
                return 1;
            } catch (DuplicateKeyException raced) {
                // Another user took the sheet's first number at the same moment: take the one after it.
            }
        }
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.time.temporal.ChronoUnit;

/**
 * What makes an overdue claim's late charge: the sheet's late percent (two decimals), its terms (days after a claim's
 * date by which it is due) and its today. The charge is never bound by a statement: it follows the sheet's today.
 * It also carries the sheet's policy date, which decides how a claim's live figures round.
 */
public record Late(BigDecimal pct, int terms, LocalDate today, LocalDate policy) {

    /**
     * How the claim's live figures round: half up when it rounds on a date (its own, or for a correction the date of
     * the claim it corrects) before the policy date, half to even on or after it.
     */
    public RoundingMode rounding(Claim claim) {
        return LocalDate.parse(claim.roundsOn()).isBefore(policy) ? RoundingMode.HALF_UP : RoundingMode.HALF_EVEN;
    }

    /** Whether the claim is overdue: OPEN with its due-by (its date plus the terms) before the sheet's today. */
    public boolean overdue(Claim claim) {
        return claim.status() == ClaimStatus.OPEN && LocalDate.parse(claim.date()).plusDays(terms).isBefore(today);
    }

    /**
     * The claim's late charge on its figure: the late percent of the figure for every full 30 days it is overdue,
     * rounded in hundredths by the claim's {@link #rounding}; 0.00 when it is not overdue, and always for a correction.
     */
    public BigDecimal charge(Claim claim, BigDecimal figure) {
        if (figure == null || claim.correction() || !overdue(claim)) {
            return BigDecimal.ZERO.setScale(2);
        }
        long days = ChronoUnit.DAYS.between(LocalDate.parse(claim.date()).plusDays(terms), today);
        return figure.multiply(pct).multiply(BigDecimal.valueOf(days / 30)).movePointLeft(2).setScale(2,
                rounding(claim));
    }
}
