package net.officefloor.hq.app.statement;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.claim.Claims;
import net.officefloor.hq.app.claim.Late;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.rate.Rate;
import net.officefloor.hq.app.rate.Rates;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.sheet.SheetClock;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/**
 * Takes a statement of the person: records their due-total now (late charges included), binds each of their
 * counting claims to the figure it has now (without its late charge) and unbinds the rest. The due-total is n/a
 * when their grade has no rate on the sheet's today, unless a
 * counting claim has a figure apart from it (settled, bound, or at another grade in force on its date): then it is the figures there are.
 */
public class TakeStatement {
    public void take(@PathVariable("sheet") String sheet, @RequestParam("user") String user, @Val Person person,
            Claims claims, Rates rates, Statements statements, SheetClock clock, Settings settings, Audit audit,
            Rollup rollup) {
        Rollup.Snapshot before = rollup.take(sheet);
        LocalDate today = clock.today(sheet);
        List<Rate> sheetRates = rates.list(sheet);
        BigDecimal floor = settings.floor(sheet);
        Late late = settings.late(sheet, today);
        List<Claim> mine = claims.list(sheet).stream().filter((c) -> c.person() == person.id()).toList();
        boolean na = Rate.on(sheetRates, person.grade(), today) == null
                && mine.stream().noneMatch((c) -> c.counts(person.held()) && person.figureApartFrom(c, today, sheetRates, floor));
        BigDecimal total = BigDecimal.ZERO.setScale(2);
        int count = 0;
        for (Claim claim : mine) {
            if (claim.counts(person.held())) {
                // The statement binds the figure; the late charge keeps following the sheet's today.
                claims.setStated(sheet, claim.id(), true, claim.figure(sheetRates, person.gradeOn(claim.date()), floor, late.rounding(claim)));
                BigDecimal due = claim.due(sheetRates, person.gradeOn(claim.date()), floor, late);
                total = due == null ? total : total.add(due);
                count++;
            } else if (claim.stated()) {
                claims.setStated(sheet, claim.id(), false, null);
            }
        }
        BigDecimal dueTotal = na ? null : total;
        statements.add(sheet, person.id(), dueTotal, today);
        audit.record("STATEMENT sheet=" + sheet + " by=" + user + " name=" + person.name() + " due-total="
                + (dueTotal == null ? "n/a" : dueTotal.toPlainString()) + " claims=" + count);
        rollup.record(sheet, user, before);
    }
}
package net.officefloor.hq.app.person;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.List;
import net.officefloor.hq.app.claim.Claim;
import net.officefloor.hq.app.rate.Rate;

/**
 * A person on a sheet: name (unique on the sheet, ignoring case) and grades (A, B or C), each in force from its
 * from-date; grade is the one in force on the sheet's today. The version is raised by one on every save. The
 * retired-from date (yyyy-mm-dd) is null unless they are retired; once it is set they count as retired, whatever
 * the date. While held, their OPEN claims count in no live total.
 */
public record Person(long id, String name, String grade, long version, String retiredFrom, boolean held,
        List<GradeFrom> grades) {

    /** Whether a claim dated {@code date} is after this person's retirement, and so refused. */
    public boolean retiredBefore(LocalDate date) {
        return retiredFrom != null && date.isAfter(LocalDate.parse(retiredFrom));
    }

    /** The grade in force on the date: the one whose from-date is the latest on or before it (null when none). */
    public String gradeOn(LocalDate date) {
        return gradeOn(grades, date);
    }

    /**
     * Whether the claim has a figure apart from the grade in force on {@code today}: one it keeps (settled or
     * bound), or one at another grade, in force on its date. Their due-total is n/a only when no claim does and
     * that grade has no rate on today.
     */
    public boolean figureApartFrom(Claim claim, LocalDate today, List<Rate> rates, BigDecimal floor) {
        String then = gradeOn(claim.date());
        return claim.fixed()
                || (then != null && !then.equals(gradeOn(today)) && claim.figure(rates, then, floor) != null);
    }

    /** The grade in force on the claim's date (yyyy-mm-dd). */
    public String gradeOn(String date) {
        return gradeOn(LocalDate.parse(date));
    }

    static String gradeOn(List<GradeFrom> grades, LocalDate date) {
        GradeFrom found = null;
        for (GradeFrom g : grades) {
            if (g.from() != null && LocalDate.parse(g.from()).isAfter(date)) {
                continue;
            }
            if (found == null || (found.from() != null && g.from() != null && g.from().compareTo(found.from()) > 0)
                    || (found.from() == null && g.from() != null)) {
                found = g;
            }
        }
        return found == null ? null : found.grade();
    }
}
